from urllib.parse import urlsplit,urlunsplit

def canon(u):
    try:
        p=urlsplit(u or '')
        return urlunsplit((p.scheme,p.netloc,p.path,'',''))
    except Exception:
        return u

def extract_dedup(results):
    out=[]
    for r in results:
        d=(r.get('response',{}) or {}).get('data') or (r.get('response',{}) or {}).get('data_preview') or {}
        res=d.get('results',d) or {}
        for c in res.get('citations',[]) or []:
            url=c.get('url') or c.get('id')
            out.append({'title':c.get('title',''),'url':url,'snippet':c.get('snippet') or c.get('text','')})
    seen=set(); dedup=[]
    for x in out:
        u=canon(x.get('url'))
        if u and u not in seen:
            seen.add(u); x['url']=u; dedup.append(x)
    return dedup
